// Regenerates vendor/lucide-subset.js from vendor/lucide.min.js, keeping only
// the icons the game references. Run after adding an icon:
//   node vendor/build-lucide-subset.cjs
// The emitted createIcons() mirrors lucide v0.468's replacement logic exactly
// (attribute merge order, class list, data-lucide retained on the svg).
const fs=require('fs'),path=require('path');
const root=path.join(__dirname,'..');
const lucide=require('./lucide.min.js');

const usedIcons=()=>{
  const names=new Set();
  const sources=fs.readdirSync(root).filter(f=>/\.(js|html)$/.test(f)&&!/^bench/.test(f));
  for(const file of sources){
    const text=fs.readFileSync(path.join(root,file),'utf8');
    for(const m of text.matchAll(/data-lucide="([a-z0-9-]+)"/g))names.add(m[1]);
    for(const m of text.matchAll(/\bicon:\s*'([a-z0-9-]+)'/g))names.add(m[1]);
    for(const m of text.matchAll(/\bentry\('[^']*','[^']*','[^']*','([a-z0-9-]+)'/g))names.add(m[1]);
  }
  return [...names].sort();
};
const pascal=name=>name.replace(/(\w)(\w*)(_|-|\s*)/g,(_,a,b)=>a.toUpperCase()+b.toLowerCase());

function build(){
  const names=usedIcons(),icons={};
  for(const name of names){
    const node=lucide.icons[pascal(name)];
    if(!node)throw new Error(`lucide has no icon "${name}"`);
    icons[pascal(name)]=node[2];
  }
  const defaults=lucide.icons.X[1];
  const source=`/**
 * Subset of lucide v0.468.0 (ISC license) generated by vendor/build-lucide-subset.cjs.
 * ${names.length} icons: ${names.join(' ')}
 */
(function(){"use strict";
var h=${JSON.stringify(defaults)},icons=${JSON.stringify(icons)};
var el=function(tag,attrs,children){var node=document.createElementNS("http://www.w3.org/2000/svg",tag);Object.keys(attrs).forEach(function(k){node.setAttribute(k,String(attrs[k]));});(children||[]).forEach(function(c){node.appendChild(el(c[0],c[1],c[2]));});return node;};
var pascal=function(n){return n.replace(/(\\w)(\\w*)(_|-|\\s*)/g,function(_,a,b){return a.toUpperCase()+b.toLowerCase();});};
var replace=function(t,nameAttr){var name=t.getAttribute(nameAttr);if(name==null)return;var children=icons[pascal(name)];if(!children)return console.warn(t.outerHTML+" icon name was not found in the provided icons object.");
var own={};Array.from(t.attributes).forEach(function(a){own[a.name]=a.value;});
var attrs=Object.assign({},h,{"data-lucide":name},own),seen=[];["lucide","lucide-"+name].concat(own.class?own.class.split(" "):[]).map(function(c){return c.trim();}).forEach(function(c){if(c&&seen.indexOf(c)<0)seen.push(c);});
attrs.class=seen.join(" ");var svg=el("svg",attrs,children);if(t.parentNode)t.parentNode.replaceChild(svg,t);};
// Like lucide 0.468, the whole document is scanned regardless of options.root.
window.lucide={icons:icons,createIcons:function(){Array.from(document.querySelectorAll("[data-lucide]")).forEach(function(t){replace(t,"data-lucide");});}};
})();
`;
  fs.writeFileSync(path.join(__dirname,'lucide-subset.js'),source);
  return names;
}
if(require.main===module)console.log(`wrote vendor/lucide-subset.js with ${build().length} icons`);
module.exports={usedIcons,pascal};
